  "discovery/github/repos/{owner}/{repo}/issues/{issueNumber}/comments/.schema.json": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"title\": \"GitHub issue comment\",\n  \"description\": \"Full resource record schema. Fields marked readOnly are synced from the provider and cannot be written by agents.\",\n  \"type\": \"object\",\n  \"required\": [\n    \"body\"\n  ],\n  \"properties\": {\n    \"body\": {\n      \"type\": \"string\",\n      \"description\": \"The contents of the comment.\"\n    },\n    \"id\": {\n      \"type\": \"string\",\n      \"description\": \"Provider canonical record id.\",\n      \"readOnly\": true\n    },\n    \"createdAt\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"Provider creation timestamp.\",\n      \"readOnly\": true\n    },\n    \"updatedAt\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"Provider last update timestamp.\",\n      \"readOnly\": true\n    },\n    \"url\": {\n      \"type\": \"string\",\n      \"format\": \"uri\",\n      \"description\": \"Provider URL for the record.\",\n      \"readOnly\": true\n    },\n    \"identifier\": {\n      \"type\": \"string\",\n      \"description\": \"Provider human-readable identifier or key.\",\n      \"readOnly\": true\n    },\n    \"provider\": {\n      \"type\": \"string\",\n      \"description\": \"Relayfile provider name.\",\n      \"readOnly\": true\n    },\n    \"objectType\": {\n      \"type\": \"string\",\n      \"description\": \"Relayfile object type.\",\n      \"readOnly\": true\n    },\n    \"objectId\": {\n      \"type\": \"string\",\n      \"description\": \"Relayfile object id.\",\n      \"readOnly\": true\n    },\n    \"workspaceId\": {\n      \"type\": \"string\",\n      \"description\": \"Relayfile workspace id.\",\n      \"readOnly\": true\n    },\n    \"connectionId\": {\n      \"type\": \"string\",\n      \"description\": \"Relayfile connection id.\",\n      \"readOnly\": true\n    },\n    \"_webhook\": {\n      \"type\": \"object\",\n      \"description\": \"Provider webhook metadata captured during sync.\",\n      \"readOnly\": true,\n      \"additionalProperties\": true\n    },\n    \"_connection\": {\n      \"type\": \"object\",\n      \"description\": \"Relayfile connection metadata captured during sync.\",\n      \"readOnly\": true,\n      \"additionalProperties\": true\n    }\n  },\n  \"additionalProperties\": false,\n  \"x-relayfile-source\": {\n    \"operationId\": \"issues/create-comment\",\n    \"sourceKind\": \"openapi\",\n    \"sourcePath\": \"scripts/integration-contracts/github/source/openapi.yaml\",\n    \"sourceUrl\": \"https://raw.githubusercontent.com/github/rest-api-description/main/descriptions/api.github.com/api.github.com.yaml\"\n  }\n}\n",
